// Default configuration for viem implementation
const defaultConfig = {
  apiUrl: "https://routeapi.symphony.ag",
  timeout: 10000,
  chainId: 1329,
  chainName: "sei",
  rpcUrl: "https://evm-rpc.sei-apis.com",
  nativeAddress: "0x0",
  wrappedNativeAddress: "0xe30fedd158a2e3b13e9badaeabafc5516e95e8c7",
  slippage: "1",
  publicClient: undefined,
  functionName: "executeSwaps",
  multicall: "0xcA11bde05977b3631167028862bE2a173976CA11",
  additionalTokens: {},
  overrideDefaultTokens: false, // When true, only use additionalTokens instead of merging with default list
  feeParams: {
    paramFee: "0",
    feeAddress: "0x0000000000000000000000000000000000000000",
    feeSharePercentage: "0",
  },
};
// Create the initial publicClient
const initialPublicClient = createPublicClient({
  chain: sei,
  transport: http(defaultConfig.rpcUrl),
});

// Initialize the current configuration with the publicClient
let currentConfig = { ...defaultConfig, publicClient: initialPublicClient };

const getConfig = () => {
  // Get additional tokens from the config
  const additionalTokens = currentConfig.additionalTokens || {};

  let finalTokens = {};

  // Check if we should override the default token list
  if (currentConfig.overrideDefaultTokens) {
    // Only use additional tokens
    finalTokens = additionalTokens;
  } else {
    // Get the default token list for the current chain
    const defaultTokens = TokenListByAddress[currentConfig.chainId] || {};

    // Create a normalized version of default tokens with lowercase addresses
    const normalizedDefaultTokens = {};
    Object.entries(defaultTokens).forEach(([address, token]) => {
      const lowerAddress = address.toLowerCase();
      // Ensure token address in attributes is also lowercase
      const normalizedToken = {
        ...token,
        attributes: {
          ...token.attributes,
          address: token.attributes.address.toLowerCase(),
        },
      };
      normalizedDefaultTokens[lowerAddress] = normalizedToken;
    });

    // Merge default tokens with additional tokens (default tokens take precedence)
    // Additional tokens are already normalized in validateAdditionalTokens
    finalTokens = {
      ...additionalTokens,
      ...normalizedDefaultTokens,
    };
  }

  return {
    ...currentConfig,
    tokens: finalTokens,
  };
};

const setConfig = (newConfig = {}) => {
  // Validate functionName if provided
  if (newConfig.functionName && newConfig.functionName !== "executeSwaps") {
    throw new Error('Invalid functionName. Must be either "executeSwaps"');
  }

  // Validate and normalize additionalTokens if provided
  if (newConfig.additionalTokens) {
    newConfig.additionalTokens = validateAdditionalTokens(
      newConfig.additionalTokens
    );
  }
  //Validate feeParams
  if (newConfig?.feeParams) {
    if (
      !String(newConfig?.feeParams?.feeAddress) ||
      !String(newConfig?.feeParams?.paramFee) ||
      !String(newConfig?.feeParams?.feeSharePercentage)
    )
      throw new Error(
        "Missing split fee parameters! paramFee, feeAddress, feeShareePercentage parameters are required for enabling custom fee split behavior."
      );

    //check fee address is valid
    if (!/^0x[a-fA-F0-9]{40}$/.test(newConfig.feeParams.feeAddress))
      throw new Error("feeAddress must be a valid ethereum address!");
    //check fee share perc. is valid
    if (!Number(newConfig.feeParams.feeSharePercentage))
      throw new Error(
        "feeSharePercentage must be a number or string representing a number! "
      );
    //check fee share perc. is between 0 - 100%
    if (
      Number(newConfig.feeParams.feeSharePercentage) > 1000 ||
      Number(newConfig.feeParams.feeSharePercentage) < 0
    )
      throw new Error(
        "feeSharePercentage must represent a percentage in bps. Should be between 0 and 1000. (1000 = 100%)"
      );
    //check fee param perc. is valid
    if (!Number(newConfig.feeParams.paramFee))
      throw new Error(
        "paramFee must be a number or string representing a number! "
      );
    //check paramFee perc. is between 0 - 100%
    if (
      Number(newConfig.feeParams.paramFee) >= 1000 ||
      Number(newConfig.feeParams.paramFee) < 0
    )
      throw new Error(
        "paramFee must represent a percentage in bps. Should be between 0 and 1000. (1000 = 100%)"
      );
  }

  if (
    newConfig?.nativeAddress &&
    newConfig?.nativeAddress !== currentConfig.nativeAddress
  ) {
    //Restructure token list if theres any change to nativeAddress
    const newChainId = newConfig?.chainId || currentConfig.chainId;
    // Create a deep copy of the token list for this chain
    TokenListByAddress[newChainId] = {
      ...TokenListByAddress[newChainId],
    };

    // Move the native token to the new address in static list
    const nativeToken =
      TokenListByAddress[newChainId][currentConfig.nativeAddress];
    TokenListByAddress[newChainId][newConfig.nativeAddress] = {
      ...nativeToken,
      attributes: {
        ...nativeToken.attributes,
        address: newConfig.nativeAddress,
      },
    };
    delete TokenListByAddress[newChainId][currentConfig.nativeAddress];
  }

  // Check if rpcUrl has changed and recreate publicClient if needed
  const shouldRecreateClient =
    newConfig.rpcUrl && newConfig.rpcUrl !== currentConfig.rpcUrl;

  // Update the current config
  currentConfig = {
    ...currentConfig,
    ...newConfig,
  };
  // Recreate publicClient if rpcUrl has changed
  if (shouldRecreateClient) {
    const updatedPublicClient = createPublicClient({
      chain: sei,
      transport: http(currentConfig.rpcUrl),
    });
    currentConfig.publicClient = updatedPublicClient;
  }
};

// Function to validate and normalize additional tokens
const validateAdditionalTokens = (tokens) => {
  if (!tokens || typeof tokens !== "object" || Array.isArray(tokens)) {
    throw new Error(
      "additionalTokens must be an object with token addresses as keys"
    );
  }

  // Create a new normalized tokens object
  const normalizedTokens = {};

  // Check each token's structure and normalize addresses
  Object.entries(tokens).forEach(([address, token]) => {
    // Validate address format
    if (!address.startsWith("0x")) {
      throw new Error(`Token address must start with '0x': ${address}`);
    }

    // Validate token structure
    if (!token || typeof token !== "object") {
      throw new Error(`Token at address ${address} must be an object`);
    }

    // Check if token has id and attributes
    if (!token.id) {
      throw new Error(`Token at address ${address} must have an 'id' property`);
    }

    if (!token.attributes || typeof token.attributes !== "object") {
      throw new Error(
        `Token at address ${address} must have an 'attributes' object`
      );
    }

    // Validate required attributes
    const requiredAttributes = ["address", "name", "symbol", "decimals"];
    for (const attr of requiredAttributes) {
      if (token.attributes[attr] === undefined) {
        throw new Error(
          `Token at address ${address} is missing required attribute: ${attr}`
        );
      }
    }

    // Ensure address in attributes matches the key (case-insensitive)
    if (token.attributes.address.toLowerCase() !== address.toLowerCase()) {
      throw new Error(
        `Token address mismatch: key is ${address} but attributes.address is ${token.attributes.address}`
      );
    }

    // Normalize the token address in attributes to lowercase
    const normalizedAddress = address.toLowerCase();
    const normalizedToken = {
      ...token,
      id: token.id.toLowerCase(), // Lowercase the id
      attributes: {
        ...token.attributes,
        address: normalizedAddress, // Ensure address is lowercase
      },
    };

    // Add to normalized tokens object with lowercase key
    normalizedTokens[normalizedAddress] = normalizedToken;
  });

  // Replace the original tokens with normalized ones
  return normalizedTokens;
};

/**
 * Gets the input token address from a route array. 
 * @param {Array} route - The route array from getRoute response
 *   Each step object must contain a tokenIn property.
 * 
 * @returns {string|undefined} The input token address or undefined if route is invalid
 *   - Returns in token contract address for valid routes
 * 
 * @example
 * // Example 1: Get input token for SEI -> USDC route
 * const route = await getRoute({
 *   tokenIn: "0x0", // SEI
 *   tokenOut: "0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48", // USDC
 *   amountIn: '1'
 * });
 * const tokenIn = getTokenIn(route);
 * console.log(tokenIn); // "0xe30fedd158a2e3b13e9badaeabafc5516e95e8c7"
 * @note This function returns WSEI address for native SEI input too. getRouteDetails function handles SEI inputs but this function does not. Careful when using externally.
 */
const getTokenIn = (route) => {
  if (!route || !Array.isArray(route)) {
    console.error("Invalid or missing `route`: Must be an array.");
    return undefined;
  }
  return route[0][0].tokenIn;
};

/**
 * Calculates the total input amount across all paths in a route.
 * 
 * @param {Array} route - Route array from getRoute
 * 
 * @returns {Object} Route input details
 * @returns {bigint} .amountIn - Total input amount in raw units
 * @returns {string} .amountInFormatted - Total input amount formatted with token decimals
 * @returns {string} .tokenIn - Input token address
 * @returns {string} .tokenOut - Output token address
 * 
 * @throws {Error} If route is invalid or missing
 * 
 * @example
 * // Example 1: Get total input for a single-path route
 * const input = getTotalAmountIn(route);
 * console.log(input.amountInFormatted); // "1.0"
 * 
 * 
 * @note
 * - Returns undefined values if route is invalid
 * - Sums amountIn from first step of each path for total input
 * - Uses token decimals from config for formatting
 */
const getTotalAmountIn = (route) => {
  if (!route || !Array.isArray(route)) {
    console.error("Invalid or missing `route`: Must be an array.");
    return {
      amountIn: undefined,
      amountInFormatted: undefined,
      tokenIn: undefined,
      tokenOut: undefined,
    };
  }
  const { tokens } = getConfig();
  const tokenIn = tokens[route[0][0].tokenIn];
  const tokenOut = tokens[route[0].at(-1).tokenOut];

  let totalAmountIn = 0n;

  for (let i = 0; i < route.length; i++) {
    totalAmountIn = totalAmountIn + BigInt(route[i][0]?.amountIn);
  }

  return {
    amountIn: totalAmountIn,
    amountInFormatted: formatUnits(totalAmountIn, tokenIn.attributes.decimals),
    tokenIn: tokenIn.attributes.address,
    tokenOut: tokenOut.attributes.address,
  };
};

